bool UserGroups::validateJsonForCreation(const Json::Value &pJson, std::string &err)
{
    if(pJson.isMember("id"))
    {
        if(!validJsonOfField(0, "id", pJson["id"], err, true))
            return false;
    }
    if(pJson.isMember("title"))
    {
        if(!validJsonOfField(1, "title", pJson["title"], err, true))
            return false;
    }
    else
    {
        err="The title column cannot be null";
        return false;
    }
    if(pJson.isMember("parent_id"))
    {
        if(!validJsonOfField(2, "parent_id", pJson["parent_id"], err, true))
            return false;
    }
    if(pJson.isMember("roles"))
    {
        if(!validJsonOfField(3, "roles", pJson["roles"], err, true))
            return false;
    }
    if(pJson.isMember("active_users"))
    {
        if(!validJsonOfField(4, "active_users", pJson["active_users"], err, true))
            return false;
    }
    if(pJson.isMember("blocked_users"))
    {
        if(!validJsonOfField(5, "blocked_users", pJson["blocked_users"], err, true))
            return false;
    }
    if(pJson.isMember("created_by"))
    {
        if(!validJsonOfField(6, "created_by", pJson["created_by"], err, true))
            return false;
    }
    if(pJson.isMember("created_at"))
    {
        if(!validJsonOfField(7, "created_at", pJson["created_at"], err, true))
            return false;
    }
    if(pJson.isMember("modified_by"))
    {
        if(!validJsonOfField(8, "modified_by", pJson["modified_by"], err, true))
            return false;
    }
    if(pJson.isMember("modified_at"))
    {
        if(!validJsonOfField(9, "modified_at", pJson["modified_at"], err, true))
            return false;
    }
    return true;
}
